function check(input, actual, expected) {
  const arr = [...input[0]];
  const n = arr.length;
  if (!Array.isArray(actual) || actual.length > 10 * n) return false;
  for (const k of actual) {
    if (!Number.isInteger(k) || k < 1 || k > n) return false;
    const head = arr.slice(0, k).reverse();
    for (let i = 0; i < k; i++) arr[i] = head[i];
  }
  return arr.every((value, i) => value === i + 1);
}

