function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100) return 'arr needs 1 to 100 values.';
  const seen = new Set(arr);
  if (seen.size !== arr.length || arr.some(v => !Number.isInteger(v) || v < 1 || v > arr.length)) return 'arr must hold each number from 1 to arr.length exactly once.';
  return null;
}

