function pancakeSort(arr) {
  const flips = [];
  const flip = (k) => {
    for (let left = 0, right = k - 1; left < right; left++, right--) {
      [arr[left], arr[right]] = [arr[right], arr[left]];
    }
    flips.push(k);
  };
  for (let size = arr.length; size > 1; size--) {
    const index = arr.indexOf(size);
    if (index === size - 1) {
      continue;
    }
    if (index > 0) {
      flip(index + 1);
    }
    flip(size);
  }
  return flips;
}

