function pancakeSort(arr) {
  let current = arr.slice();
  const result = [];
  for (let end = current.length; end > 1; end--) {
    let best = 0;
    for (let i = 1; i < end; i++) if (current[i] > current[best]) best = i;
    result.push(best + 1);
    current = current.slice(0, best + 1).reverse().concat(current.slice(best + 1));
    result.push(end);
    current = current.slice(0, end).reverse().concat(current.slice(end));
  }
  return result;
}

