function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const arr = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  // Sometimes return an already sorted array so that the no-flip case is exercised.
  if (size === 'small' && rand() < 0.2) arr.sort((a, b) => a - b);
  return [arr];
}
